async function clearICC(req, res) {
    try {
        console.log("@clearICC")
        if (req.body.hasOwnProperty("nn")) {

            // get total absolute value + clear previous ancestor values
            for await (let tempNodeID of Object.values(req.body["nn"])) {
                let ancestorNode = runtime._.nodes.getNode(tempNodeID)
                ancestorNode.status({});
                ancestorNode.highlightintrinsiceffects = false
            }
        }
        res.status(200).send("Successfully cleared all ICC values")

    } catch (exception) {
        console.log("Excpetion ", exception)
        res.status(500).send({ error: exception })
    }
}
async function updateICC(req, res) {
    try {
        let _fn = "@ updateICC"
        if (req.body.hasOwnProperty("icc") && req.body.hasOwnProperty("nodeID")) {
            let nodeID = req.body["nodeID"]
            let icc = req.body["icc"]
            console.log(icc)
            let nn = req.body["nn"]
            if (typeof icc === "string") {
                icc = icc.replace(/'/g, '"')
                icc = icc.replace(/\(/g, '')
                icc = icc.replace(/\)/g, '')
                if (icc.includes("array")) {
                    icc = icc.replaceAll("array", "")
                }
                if (icc.includes("True")) {
                    icc = icc.replaceAll("True", "true")
                }
                if (icc.includes("None")) {
                    icc = icc.replaceAll("None", "null")
                }
                if (icc.includes("False")) {
                    icc = icc.replaceAll("False", "false")
                }
                icc = JSON.parse(icc)
            }
            if (icc.hasOwnProperty("median")) {
                let total_abs = 0
                // get total absolute value + clear previous ancestor values
                for await (let tempNodeID of Object.values(nn)) {
                    let ancestorNode = runtime._.nodes.getNode(tempNodeID)
                    //its a node that needs to update its status
                    if (Object.keys(icc["median"]).includes(ancestorNode.name)) {
                        console.log(icc['median'][ancestorNode.name])
                        total_abs += icc['median'][ancestorNode.name]
                    }
                    ancestorNode.highlightintrinsiceffects = false
                    ancestorNode.status({});
                }

                // update ancestor nodes with new status
                for await (let tempNodeName of Object.keys(icc["median"])) {
                    let ancestorNode = runtime._.nodes.getNode(nn[tempNodeName])
                    let value = icc["median"][tempNodeName]
                    value = (typeof value === "string") ? Number.parseFloat(value) : value
                    value = (value / total_abs * 100)

                    console.log(`${_fn} value `, value)
                    // calculate number of decimals needed 
                    let decimalCount = Math.abs(value - Math.floor(value))
                    if (decimalCount <= 0.9) {
                        decimalCount = 2
                    } else {
                        decimalCount = 5
                    }

                    let fill = "green"
                    value = value.toLocaleString(undefined, { maximumFractionDigits: 2, minimumFractionDigits: 0 })
                    if (value < 0) {
                        fill = "red"
                    }
                    if (value === "-0" || value === "0") {
                        fill = "grey"
                        value = "0"
                    }
                    console.log(`${_fn} value 2 `, value)
                    ancestorNode.status({ "fill": fill, "shape": "dot", "text": value + "%" });
                }
            }

        }
        res.status(200).send("Successfully updated ICC values")

    } catch (exception) {
        console.log("Excpetion ", exception)
        res.status(500).send({ error: exception })
    }
}

async function updateCausalMechanism(req, res) {
    try {
        let _fn = `@@updateCausalMechanism`
        console.log(_fn, " request :  ", req.body)
        // call api server to handle processing data info
        let causal_inf_uri = uri + ":" + port + "/update-causal-mechanism/" + req.body["model_id"]
        console.log(_fn, " causal inf uri:  ", causal_inf_uri)

        try {
            await axios({
                method: "post",
                url: causal_inf_uri,
                data: req.body
            }).then(async (api_res) => {
                if (api_res.status !== 200) {
                    throw api_res.statusText
                } else {
                    let node = runtime._.nodes.getNode(req.body.node_id)
                    if (api_res.data.hasOwnProperty("causalmechanism")) {
                        node.causalmechanism = api_res.data.causalmechanism
                    }
                    if (api_res.data.hasOwnProperty("edgestrength")) {
                        node.edgestrength = api_res.data.edgestrength
                    }
                    console.log(node.causalmechanism)
                    console.log(node.edgestrength)
                    console.log(_fn, " Successully updated causal mechanism", api_res.data)
                    res.send(api_res.data)
                }
            }).catch((err) => {
                console.log(causal_inf_uri, Object.keys(err))
                console.log(err.response)
                throw err.response.statusText
            })
        } catch (exception) {
            console.log(_fn, " exception ", exception.response)
            res.status(500).send({ error: exception })
        }
    } catch (exception) {
        console.log("ERROR while udpatingCausalMechanism", exception.toString())
    }
}

